<?php
declare(strict_types=1);

namespace Erp\Modules\Manufacturing;

use Erp\Core\Security\Authorization;
use Erp\Core\Security\UserContext;
use Erp\Modules\Inventory\StockMoveRepository;
use DateTimeImmutable;
use DateTimeZone;
use InvalidArgumentException;
use PDO;
use Throwable;

/** Company-scoped BoMs, work centers, and the first end-to-end production flow. */
final class ManufacturingRepository
{
    public function __construct(private readonly PDO $pdo) {}

    public function options(UserContext $user, Authorization $authorization, mixed $rawCompanyId): array
    {
        $companyId = $this->companyId($user, $authorization, $rawCompanyId);
        $products = $this->pdo->prepare("SELECT p.id,p.name,p.internal_reference,p.tracking,p.uom_id,u.abbreviation AS uom FROM products p JOIN units_of_measure u ON u.id=p.uom_id WHERE p.company_id=:company AND p.active=1 AND p.product_type='goods' ORDER BY p.name,p.id");
        $products->execute(['company' => $companyId]);
        $uoms = $this->pdo->prepare('SELECT u.id,u.name,u.abbreviation,u.category_id FROM units_of_measure u JOIN uom_categories c ON c.id=u.category_id WHERE u.active=1 AND c.active=1 AND (u.company_id IS NULL OR u.company_id=:uom_company) AND (c.company_id IS NULL OR c.company_id=:category_company) ORDER BY c.name,u.factor_to_reference DESC,u.name');
        $uoms->execute(['uom_company' => $companyId, 'category_company' => $companyId]);
        $locations = $this->pdo->prepare('SELECT id,name,complete_name,location_usage,warehouse_id FROM stock_locations WHERE company_id=:company AND active=1 AND location_usage IN (\'internal\',\'transit\',\'production\') ORDER BY location_usage,complete_name,id');
        $locations->execute(['company' => $companyId]);
        $centers = $this->pdo->prepare('SELECT id,code,name,capacity,time_efficiency,cost_per_hour,active FROM manufacturing_work_centers WHERE company_id=:company ORDER BY active DESC,name,id');
        $centers->execute(['company' => $companyId]);
        $boms = $this->pdo->prepare('SELECT b.id,b.code,b.product_id,p.name AS product_name,b.product_quantity,b.uom_id,u.abbreviation AS uom,b.active FROM manufacturing_boms b JOIN products p ON p.id=b.product_id JOIN units_of_measure u ON u.id=b.uom_id WHERE b.company_id=:company ORDER BY b.active DESC,p.name,b.id');
        $boms->execute(['company' => $companyId]);
        $lots = $this->pdo->prepare('SELECT q.product_id,q.lot_id,l.lot_code,l.expiration_date,q.location_id,SUM(q.quantity-q.reserved_quantity) AS available_quantity FROM stock_quants q JOIN stock_locations loc ON loc.id=q.location_id LEFT JOIN stock_lots l ON l.id=q.lot_id WHERE q.company_id=:company AND loc.location_usage IN (\'internal\',\'transit\') AND q.lot_id IS NOT NULL AND q.quantity>q.reserved_quantity GROUP BY q.product_id,q.lot_id,l.lot_code,l.expiration_date,q.location_id ORDER BY q.product_id,l.expiration_date,l.lot_code');
        $lots->execute(['company' => $companyId]);
        return ['company_id' => $companyId, 'company_timezone' => $this->companyTimezone($companyId), 'company_currency' => $this->companyCurrency($companyId), 'products' => $products->fetchAll(), 'uoms' => $uoms->fetchAll(), 'locations' => $locations->fetchAll(), 'work_centers' => $centers->fetchAll(), 'boms' => $boms->fetchAll(), 'available_lots' => $lots->fetchAll()];
    }

    public function workCenters(UserContext $user, Authorization $authorization, mixed $rawCompanyId): array
    {
        $companyId = $this->companyId($user, $authorization, $rawCompanyId);
        $query = $this->pdo->prepare('SELECT id,company_id,code,name,capacity,time_efficiency,cost_per_hour,active,created_at,updated_at FROM manufacturing_work_centers WHERE company_id=:company ORDER BY active DESC,name,id');
        $query->execute(['company' => $companyId]);
        return ['records' => $query->fetchAll(), 'company_id' => $companyId];
    }

    public function saveWorkCenter(?int $id, array $input, UserContext $user, Authorization $authorization, int $actorId, string $remoteAddress): array
    {
        $allowed = ['company_id','code','name','capacity','time_efficiency','cost_per_hour','active'];
        $this->rejectUnknown($input, $allowed);
        $companyId = $this->companyId($user, $authorization, $input['company_id'] ?? null);
        $code = $this->text($input['code'] ?? '', 'Code', 32, true);
        $name = $this->text($input['name'] ?? '', 'Name', 120, true);
        $this->assertScale($input['capacity'] ?? '1', 4, 'Capacity');
        $this->assertScale($input['time_efficiency'] ?? '100', 4, 'Time Efficiency');
        $capacity = $this->decimal($input['capacity'] ?? '1', 'Capacity', true);
        $efficiency = $this->decimal($input['time_efficiency'] ?? '100', 'Time Efficiency', true);
        $cost = $this->decimal($input['cost_per_hour'] ?? '0', 'Cost per Hour', false);
        $active = $this->boolean($input['active'] ?? true, 'Active');
        $this->assertSql('CAST(:capacity AS DECIMAL(12,4))>0 AND CAST(:capacity_max AS DECIMAL(20,6))<=99999999.9999 AND CAST(:efficiency AS DECIMAL(8,4))>0 AND CAST(:efficiency_max AS DECIMAL(20,6))<=9999.9999 AND CAST(:cost AS DECIMAL(20,6))>=0', ['capacity'=>$capacity,'capacity_max'=>$capacity,'efficiency'=>$efficiency,'efficiency_max'=>$efficiency,'cost'=>$cost], 'Capacity and efficiency must be positive and within supported precision; hourly cost cannot be negative.');
        return $this->atomic(function () use ($id,$companyId,$code,$name,$capacity,$efficiency,$cost,$active,$actorId,$remoteAddress): array {
            if ($id === null) {
                $this->pdo->prepare('INSERT INTO manufacturing_work_centers (company_id,code,name,capacity,time_efficiency,cost_per_hour,active,created_by) VALUES (:company,:code,:name,:capacity,:efficiency,:cost,:active,:actor)')->execute(['company'=>$companyId,'code'=>$code,'name'=>$name,'capacity'=>$capacity,'efficiency'=>$efficiency,'cost'=>$cost,'active'=>$active,'actor'=>$actorId]);
                $id = (int)$this->pdo->lastInsertId();
                $event = 'manufacturing.work_center.created';
            } else {
                $before = $this->workCenter($id,$companyId);
                if (!$before) throw new InvalidArgumentException('Work center was not found for this company.');
                $this->pdo->prepare('UPDATE manufacturing_work_centers SET code=:code,name=:name,capacity=:capacity,time_efficiency=:efficiency,cost_per_hour=:cost,active=:active WHERE id=:id AND company_id=:company')->execute(['code'=>$code,'name'=>$name,'capacity'=>$capacity,'efficiency'=>$efficiency,'cost'=>$cost,'active'=>$active,'id'=>$id,'company'=>$companyId]);
                $event = 'manufacturing.work_center.updated';
            }
            $saved = $this->workCenter((int)$id,$companyId) ?? throw new \RuntimeException('Saved work center could not be reloaded.');
            $this->audit($companyId,$actorId,$event,'manufacturing.work_center',(int)$id,isset($before)?$before:null,$saved,$remoteAddress);
            return $saved;
        });
    }

    public function boms(UserContext $user, Authorization $authorization, mixed $rawCompanyId, array $filters = []): array
    {
        $companyId = $this->companyId($user,$authorization,$rawCompanyId);
        $where = ['b.company_id=:company']; $params = ['company'=>$companyId];
        if (($filters['active'] ?? 'all') !== 'all') { $where[]='b.active=:active'; $params['active']=($filters['active']==='true'||$filters['active']==='1')?1:0; }
        $query=$this->pdo->prepare('SELECT b.id,b.code,b.product_id,p.name AS product_name,b.product_quantity,b.uom_id,u.abbreviation AS uom,b.bom_type,b.active,(SELECT COUNT(*) FROM manufacturing_bom_components c WHERE c.bom_id=b.id) AS component_count,(SELECT COUNT(*) FROM manufacturing_bom_operations o WHERE o.bom_id=b.id) AS operation_count FROM manufacturing_boms b JOIN products p ON p.id=b.product_id JOIN units_of_measure u ON u.id=b.uom_id WHERE '.implode(' AND ',$where).' ORDER BY b.active DESC,p.name,b.id');
        $query->execute($params); return ['records'=>$query->fetchAll(),'company_id'=>$companyId];
    }

    public function bom(int $id, UserContext $user, Authorization $authorization): ?array
    {
        $query=$this->pdo->prepare('SELECT b.*,p.name AS product_name,p.internal_reference,u.abbreviation AS uom FROM manufacturing_boms b JOIN products p ON p.id=b.product_id JOIN units_of_measure u ON u.id=b.uom_id WHERE b.id=:id LIMIT 1');
        $query->execute(['id'=>$id]);$bom=$query->fetch();if(!$bom||!$authorization->canAccessCompany((int)$bom['company_id']))return null;
        $components=$this->pdo->prepare('SELECT c.id,c.sequence_no,c.product_id,p.name AS product_name,p.tracking,c.quantity,c.uom_id,u.abbreviation AS uom,c.scrap_percent FROM manufacturing_bom_components c JOIN products p ON p.id=c.product_id JOIN units_of_measure u ON u.id=c.uom_id WHERE c.bom_id=:bom ORDER BY c.sequence_no,c.id');$components->execute(['bom'=>$id]);
        $operations=$this->pdo->prepare('SELECT o.id,o.sequence_no,o.name,o.work_center_id,w.name AS work_center_name,o.expected_duration_minutes,o.worksheet FROM manufacturing_bom_operations o JOIN manufacturing_work_centers w ON w.id=o.work_center_id WHERE o.bom_id=:bom ORDER BY o.sequence_no,o.id');$operations->execute(['bom'=>$id]);
        $bom['components']=$components->fetchAll();$bom['operations']=$operations->fetchAll();return $bom;
    }

    public function saveBom(?int $id,array $input,UserContext $user,Authorization $authorization,int $actorId,string $remoteAddress):array
    {
        $this->rejectUnknown($input,['company_id','product_id','code','product_quantity','uom_id','bom_type','active','components','operations']);
        $companyId=$this->companyId($user,$authorization,$input['company_id']??null);
        $productId=$this->positiveId($input['product_id']??null,'Finished Product');$uomId=$this->positiveId($input['uom_id']??null,'Output Unit');
        $code=$this->text($input['code']??'','BoM Reference',80,false);$quantity=$this->decimal($input['product_quantity']??null,'Output Quantity',true);
        if (($input['bom_type']??'manufacture')!=='manufacture') throw new InvalidArgumentException('This manufacturing slice supports manufacturing BoMs only.');
        $active=$this->boolean($input['active']??true,'Active');
        $components=$this->normalizeComponents($input['components']??null,$companyId,$productId);
        $operations=$this->normalizeOperations($input['operations']??[],$companyId);
        $product=$this->product($productId,$companyId);if($product['product_type']!=='goods')throw new InvalidArgumentException('A manufacturing BoM output must be a Goods product.');
        $this->sameUomCategory($uomId,(int)$product['uom_id'],$companyId,'BoM output unit and finished product unit must use the same unit category.');
        $this->assertNoCycle($companyId,$productId,$components,$id);
        $this->atomic(function()use(&$id,$companyId,$productId,$code,$quantity,$uomId,$active,$components,$operations,$actorId,$remoteAddress):void{
            if($id===null){$this->pdo->prepare('INSERT INTO manufacturing_boms (company_id,product_id,code,product_quantity,uom_id,active,created_by) VALUES (:company,:product,:code,:quantity,:uom,:active,:actor)')->execute(['company'=>$companyId,'product'=>$productId,'code'=>$code?:null,'quantity'=>$quantity,'uom'=>$uomId,'active'=>$active,'actor'=>$actorId]);$id=(int)$this->pdo->lastInsertId();$before=null;$event='manufacturing.bom.created';}
            else{$before=$this->bomForCompany($id,$companyId);if(!$before)throw new InvalidArgumentException('BoM was not found for this company.');$drafts=$this->pdo->prepare('SELECT COUNT(*) FROM manufacturing_orders WHERE bom_id=:bom');$drafts->execute(['bom'=>$id]);if((int)$drafts->fetchColumn()>0)throw new InvalidArgumentException('This BoM is referenced by an order; preserve it and create a new BoM revision instead.');$this->pdo->prepare('UPDATE manufacturing_boms SET product_id=:product,code=:code,product_quantity=:quantity,uom_id=:uom,active=:active WHERE id=:id AND company_id=:company')->execute(['product'=>$productId,'code'=>$code?:null,'quantity'=>$quantity,'uom'=>$uomId,'active'=>$active,'id'=>$id,'company'=>$companyId]);$this->pdo->prepare('DELETE FROM manufacturing_bom_components WHERE bom_id=:bom')->execute(['bom'=>$id]);$this->pdo->prepare('DELETE FROM manufacturing_bom_operations WHERE bom_id=:bom')->execute(['bom'=>$id]);$event='manufacturing.bom.updated';}
            $componentInsert=$this->pdo->prepare('INSERT INTO manufacturing_bom_components (company_id,bom_id,sequence_no,product_id,quantity,uom_id,scrap_percent) VALUES (:company,:bom,:sequence,:product,:quantity,:uom,:scrap)');
            foreach($components as $component)$componentInsert->execute(['company'=>$companyId,'bom'=>$id,'sequence'=>$component['sequence_no'],'product'=>$component['product_id'],'quantity'=>$component['quantity'],'uom'=>$component['uom_id'],'scrap'=>$component['scrap_percent']]);
            $operationInsert=$this->pdo->prepare('INSERT INTO manufacturing_bom_operations (company_id,bom_id,sequence_no,name,work_center_id,expected_duration_minutes,worksheet) VALUES (:company,:bom,:sequence,:name,:center,:duration,:worksheet)');
            foreach($operations as $operation)$operationInsert->execute(['company'=>$companyId,'bom'=>$id,'sequence'=>$operation['sequence_no'],'name'=>$operation['name'],'center'=>$operation['work_center_id'],'duration'=>$operation['expected_duration_minutes'],'worksheet'=>$operation['worksheet']]);
            $saved=$this->bomForCompany((int)$id,$companyId)??[];$this->audit($companyId,$actorId,$event,'manufacturing.bom',(int)$id,$before,$saved,$remoteAddress);
        });
        return $this->bom((int)$id,$user,$authorization)??throw new \RuntimeException('Saved BoM could not be reloaded.');
    }

    public function orders(UserContext $user,Authorization $authorization,mixed $rawCompanyId,array $filters=[]):array
    {
        $companyId=$this->companyId($user,$authorization,$rawCompanyId);$where=['m.company_id=:company'];$params=['company'=>$companyId];$state=(string)($filters['state']??'all');
        if($state!=='all'){if(!in_array($state,['draft','confirmed','in_progress','done','cancelled'],true))throw new InvalidArgumentException('Manufacturing order status filter is invalid.');$where[]='m.state=:state';$params['state']=$state;}
        $q=trim((string)($filters['q']??''));if($q!==''){if(mb_strlen($q)>120)throw new InvalidArgumentException('Search text must be 120 characters or fewer.');$where[]='(m.reference LIKE :q_ref OR p.name LIKE :q_product OR m.origin LIKE :q_origin)';$like='%'.$q.'%';$params+=['q_ref'=>$like,'q_product'=>$like,'q_origin'=>$like];}
        $query=$this->pdo->prepare('SELECT m.id,m.reference,m.bom_id,m.product_id,p.name AS product_name,m.planned_quantity,m.produced_quantity,u.abbreviation AS uom,m.scheduled_at,c.timezone AS company_timezone,m.origin,m.state,m.total_cost,m.valuation_cost,m.cost_variance FROM manufacturing_orders m JOIN products p ON p.id=m.product_id JOIN units_of_measure u ON u.id=m.uom_id JOIN companies c ON c.id=m.company_id WHERE '.implode(' AND ',$where).' ORDER BY m.created_at DESC,m.id DESC LIMIT 200');$query->execute($params);$records=$query->fetchAll();foreach($records as &$record){$record['scheduled_at']=$this->displayDateTime($record['scheduled_at'],$record['company_timezone']);unset($record['company_timezone']);}unset($record);return ['records'=>$records,'company_id'=>$companyId];
    }

    public function order(int $id,UserContext $user,Authorization $authorization):?array
    {
        $query=$this->pdo->prepare('SELECT m.*,am.name AS accounting_move_name,am.state AS accounting_move_state,p.name AS product_name,p.internal_reference,u.abbreviation AS uom,b.code AS bom_code,src.complete_name AS source_location,prodloc.complete_name AS production_location,dst.complete_name AS destination_location,c.timezone AS company_timezone,c.currency_code AS company_currency FROM manufacturing_orders m LEFT JOIN accounting_moves am ON am.id=m.accounting_move_id JOIN products p ON p.id=m.product_id JOIN units_of_measure u ON u.id=m.uom_id JOIN manufacturing_boms b ON b.id=m.bom_id JOIN stock_locations src ON src.id=m.source_location_id JOIN stock_locations prodloc ON prodloc.id=m.production_location_id JOIN stock_locations dst ON dst.id=m.destination_location_id JOIN companies c ON c.id=m.company_id WHERE m.id=:id LIMIT 1');$query->execute(['id'=>$id]);$order=$query->fetch();if(!$order||!$authorization->canAccessCompany((int)$order['company_id']))return null;
        if(!$authorization->allowsForCompany('accounting.read',(int)$order['company_id'])){$order['accounting_move_name']=null;$order['accounting_move_state']=null;}
        $components=$this->pdo->prepare('SELECT c.id,c.bom_component_id,c.product_id,p.name AS product_name,p.tracking,c.uom_id,u.abbreviation AS uom,c.required_quantity,c.consumed_quantity,c.stock_move_id,m.reference AS stock_move_reference,m.state AS stock_move_state,m.valuation_value FROM manufacturing_order_components c JOIN products p ON p.id=c.product_id JOIN units_of_measure u ON u.id=c.uom_id LEFT JOIN stock_moves m ON m.id=c.stock_move_id WHERE c.order_id=:order ORDER BY c.id');$components->execute(['order'=>$id]);
        $operations=$this->pdo->prepare('SELECT w.id,w.sequence_no,w.name,w.work_center_id,w.work_center_name,w.work_center_capacity,w.work_center_time_efficiency,w.cost_per_hour,w.expected_duration_minutes,w.actual_duration_minutes,w.worksheet,w.state,w.started_at,w.done_at FROM manufacturing_work_orders w WHERE w.order_id=:order ORDER BY w.sequence_no,w.id');$operations->execute(['order'=>$id]);
        $order['components']=$components->fetchAll();$order['work_orders']=$operations->fetchAll();$order['scheduled_at']=$this->displayDateTime($order['scheduled_at'],$order['company_timezone']);unset($order['company_timezone']);
        $moves=$this->pdo->prepare('SELECT id,reference,product_id,demand_quantity,done_quantity,valuation_value,state,source_location_id,destination_location_id FROM stock_moves WHERE origin_model=\'manufacturing\' AND origin_record_id=:order ORDER BY id');$moves->execute(['order'=>$id]);$order['stock_moves']=$moves->fetchAll();$rootId=$order['backorder_root_id']===null?$id:(int)$order['backorder_root_id'];$root=$this->pdo->prepare('SELECT reference FROM manufacturing_orders WHERE id=:root AND company_id=:company');$root->execute(['root'=>$rootId,'company'=>$order['company_id']]);$rootReference=$root->fetchColumn();$siblings=$this->pdo->prepare('SELECT id,reference,state,planned_quantity,produced_quantity,backorder_sequence FROM manufacturing_orders WHERE company_id=:company AND backorder_root_id=:root AND id<>:current ORDER BY backorder_sequence,id');$siblings->execute(['company'=>$order['company_id'],'root'=>$rootId,'current'=>$id]);$order['backorders']=$siblings->fetchAll();$order['backorder_root_reference']=$order['backorder_root_id']!==null||$order['backorders']?($rootReference?:null):null;return $order;
    }

    public function createOrder(array $input,UserContext $user,Authorization $authorization,int $actorId,string $remoteAddress):array
    {
        $this->rejectUnknown($input,['company_id','bom_id','planned_quantity','source_location_id','production_location_id','destination_location_id','scheduled_at','origin']);
        $companyId=$this->companyId($user,$authorization,$input['company_id']??null);$bomId=$this->positiveId($input['bom_id']??null,'BoM');$quantity=$this->decimal($input['planned_quantity']??null,'Planned Quantity',true);
        $bom=$this->bomForCompany($bomId,$companyId);if(!$bom||!(bool)$bom['active'])throw new InvalidArgumentException('Select an active BoM for this company.');
        $sourceId=$this->positiveId($input['source_location_id']??null,'Component Source');$productionId=$this->positiveId($input['production_location_id']??null,'Production Location');$destinationId=$this->positiveId($input['destination_location_id']??null,'Finished Goods Destination');if($sourceId===$destinationId)throw new InvalidArgumentException('Component source and finished goods destination must be different locations.');
        $source=$this->location($sourceId,$companyId,['internal','transit']);$production=$this->location($productionId,$companyId,['production']);$destination=$this->location($destinationId,$companyId,['internal']);
        $scheduled=$this->dateTime($input['scheduled_at']??null,$this->companyTimezone($companyId));$origin=$this->text($input['origin']??'','Origin',120,false);
        return $this->atomic(function()use($companyId,$bomId,$quantity,$source,$production,$destination,$scheduled,$origin,$actorId,$remoteAddress,$user,$authorization):array{
            $lock=$this->pdo->prepare('SELECT b.*,p.uom_id AS product_uom_id FROM manufacturing_boms b JOIN products p ON p.id=b.product_id WHERE b.id=:bom AND b.company_id=:company AND b.active=1 FOR UPDATE');$lock->execute(['bom'=>$bomId,'company'=>$companyId]);$bom=$lock->fetch();if(!$bom)throw new InvalidArgumentException('This BoM was archived before the order could be saved.');
            $locationIds=[(int)$source['id'],(int)$production['id'],(int)$destination['id']];sort($locationIds,SORT_NUMERIC);$lockedLocations=[];foreach($locationIds as$locationId){$lockedLocations[$locationId]=$this->location($locationId,$companyId,['internal','transit','production'],true);}
            $source=$lockedLocations[(int)$source['id']];$production=$lockedLocations[(int)$production['id']];$destination=$lockedLocations[(int)$destination['id']];
            if(!in_array($source['location_usage'],['internal','transit'],true)||$production['location_usage']!=='production'||$destination['location_usage']!=='internal')throw new InvalidArgumentException('A selected Manufacturing location changed type before the order could be saved. Reload and choose active locations.');
            $this->pdo->prepare('INSERT INTO manufacturing_orders (company_id,bom_id,product_id,planned_quantity,uom_id,source_location_id,production_location_id,destination_location_id,scheduled_at,origin,created_by) VALUES (:company,:bom,:product,:quantity,:uom,:source,:production,:destination,:scheduled,:origin,:actor)')->execute(['company'=>$companyId,'bom'=>$bomId,'product'=>$bom['product_id'],'quantity'=>$quantity,'uom'=>$bom['uom_id'],'source'=>$source['id'],'production'=>$production['id'],'destination'=>$destination['id'],'scheduled'=>$scheduled,'origin'=>$origin?:null,'actor'=>$actorId]);
            $id=(int)$this->pdo->lastInsertId();$ref='MO/'.gmdate('Y').'/'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$this->pdo->prepare('UPDATE manufacturing_orders SET reference=:ref WHERE id=:id')->execute(['ref'=>$ref,'id'=>$id]);
            $lines=$this->pdo->prepare('SELECT c.id,c.product_id,c.quantity,c.uom_id,c.scrap_percent FROM manufacturing_bom_components c WHERE c.bom_id=:bom ORDER BY c.sequence_no,c.id');$lines->execute(['bom'=>$bomId]);$insert=$this->pdo->prepare('INSERT INTO manufacturing_order_components (company_id,order_id,bom_component_id,product_id,uom_id,required_quantity) VALUES (:company,:order,:bom_line,:product,:uom,:quantity)');
            foreach($lines->fetchAll()as$line){$this->assertSql('CAST(:component_qty AS DECIMAL(20,6))>0 AND CAST(:order_qty AS DECIMAL(20,6))>0 AND CAST(:bom_qty AS DECIMAL(20,6))>0',['component_qty'=>$line['quantity'],'order_qty'=>$quantity,'bom_qty'=>$bom['product_quantity']],'A BoM component quantity could not be calculated.');$formula='CAST(:component_qty_check AS DECIMAL(50,12))*CAST(:order_qty_check AS DECIMAL(50,12))/CAST(:bom_qty_check AS DECIMAL(50,12))*(1+CAST(:scrap_check AS DECIMAL(8,4))/100)';$this->assertSql('ROUND('.$formula.',6) BETWEEN 0.000001 AND 99999999999999.999999',['component_qty_check'=>$line['quantity'],'order_qty_check'=>$quantity,'bom_qty_check'=>$bom['product_quantity'],'scrap_check'=>$line['scrap_percent']],'The calculated component quantity is outside supported Inventory precision.');$calc=$this->pdo->prepare('SELECT CAST(ROUND(CAST(:component_qty AS DECIMAL(50,12))*CAST(:order_qty AS DECIMAL(50,12))/CAST(:bom_qty AS DECIMAL(50,12))*(1+CAST(:scrap AS DECIMAL(8,4))/100),6) AS DECIMAL(20,6))');$calc->execute(['component_qty'=>$line['quantity'],'order_qty'=>$quantity,'bom_qty'=>$bom['product_quantity'],'scrap'=>$line['scrap_percent']]);$insert->execute(['company'=>$companyId,'order'=>$id,'bom_line'=>$line['id'],'product'=>$line['product_id'],'uom'=>$line['uom_id'],'quantity'=>$calc->fetchColumn()]);}
            $saved=$this->order($id,$user,$authorization)??[];$this->audit($companyId,$actorId,'manufacturing.order.created','manufacturing.order',$id,null,$saved,$remoteAddress);return $saved;
        });
    }

    public function confirmOrder(int $id,array $input,UserContext $user,Authorization $authorization,int $actorId,string $remoteAddress):array
    {
        $this->rejectUnknown($input,['component_allocations']);$allocations=$this->normalizeAllocations($input['component_allocations']??[]);
        return $this->atomic(function()use($id,$allocations,$user,$authorization,$actorId,$remoteAddress):array{
            $order=$this->lockedOrder($id,$authorization);if($order['state']!=='draft')throw new InvalidArgumentException('Only a draft Manufacturing Order can be confirmed.');
            $this->location((int)$order['source_location_id'],(int)$order['company_id'],['internal','transit'],true);
            $this->location((int)$order['production_location_id'],(int)$order['company_id'],['production'],true);
            $this->location((int)$order['destination_location_id'],(int)$order['company_id'],['internal'],true);
            $before=$this->order($id,$user,$authorization)??[];$components=$before['components'];$stock=new StockMoveRepository($this->pdo);
