        if(!is_array($raw)||!array_is_list($raw)||count($raw)>200)throw new InvalidArgumentException('Component lot allocations must be a list.');$result=[];$seen=[];foreach($raw as$row){if(!is_array($row))throw new InvalidArgumentException('Each component allocation must be an object.');$this->rejectUnknown($row,['bom_component_id','lines']);$component=$this->positiveId($row['bom_component_id']??null,'BoM Component');if(isset($seen[$component]))throw new InvalidArgumentException('A tracked component can only have one allocation entry.');$seen[$component]=true;if(!is_array($row['lines']??null)||!array_is_list($row['lines'])||count($row['lines'])<1||count($row['lines'])>500)throw new InvalidArgumentException('Enter one or more lot lines for each tracked component.');$lines=[];foreach($row['lines']as$line){if(!is_array($line))throw new InvalidArgumentException('Each component lot line must be an object.');$this->rejectUnknown($line,['lot_id','quantity']);$lines[]=['lot_id'=>$this->positiveId($line['lot_id']??null,'Lot'),'quantity'=>$this->decimal($line['quantity']??null,'Lot Quantity',true)];}$result[]=['bom_component_id'=>$component,'lines'=>$lines];}return$result;
    }

    private function normalizeOutputLots(mixed $raw):array
    {
        if(!is_array($raw)||!array_is_list($raw)||count($raw)>500)throw new InvalidArgumentException('Finished lot lines must be a list.');$result=[];foreach($raw as$line){if(!is_array($line))throw new InvalidArgumentException('Each finished lot line must be an object.');$this->rejectUnknown($line,['lot_code','expiration_date','quantity']);$result[]=['lot_code'=>$this->text($line['lot_code']??'','Lot or Serial',120,true),'expiration_date'=>$this->date($line['expiration_date']??null),'quantity'=>$this->decimal($line['quantity']??null,'Finished Quantity',true)];}return$result;
    }

    private function assertNoCycle(int $companyId,int $productId,array $components,?int $excludeBomId):void
    {
        $query=$this->pdo->prepare('SELECT b.product_id,c.product_id AS component_id FROM manufacturing_boms b JOIN manufacturing_bom_components c ON c.bom_id=b.id WHERE b.company_id=:company AND b.active=1'.($excludeBomId?' AND b.id<>'.(int)$excludeBomId:''));$query->execute(['company'=>$companyId]);$graph=[];foreach($query->fetchAll()as$row)$graph[(int)$row['product_id']][]=(int)$row['component_id'];$reaches=function(int $node,array &$seen)use(&$reaches,$graph,$productId):bool{if($node===$productId)return true;if(isset($seen[$node]))return false;$seen[$node]=true;foreach($graph[$node]??[]as$next)if($reaches($next,$seen))return true;return false;};foreach($components as$component){$seen=[];if($reaches((int)$component['product_id'],$seen))throw new InvalidArgumentException('This BoM would create a recursive manufacturing dependency.');}
    }

    private function companyId(UserContext $user,Authorization $authorization,mixed $raw):int{$value=$raw??$user->defaultCompanyId??(count($user->companyIds)===1?$user->companyIds[0]:null);$id=$this->positiveId($value,'Company');if(!$authorization->canAccessCompany($id))throw new InvalidArgumentException('The selected company is not available to your account.');return$id;}
    private function product(int $id,int $companyId):array{$q=$this->pdo->prepare('SELECT id,company_id,name,product_type,tracking,uom_id,cost_price,category_id FROM products WHERE id=:id AND company_id=:company AND active=1 LIMIT 1');$q->execute(['id'=>$id,'company'=>$companyId]);return$q->fetch()?:throw new InvalidArgumentException('Select an active product in the selected company.');}
    private function location(int $id,int $companyId,array $usages,bool $lock=false):array{$q=$this->pdo->prepare('SELECT id,company_id,name,complete_name,location_usage FROM stock_locations WHERE id=:id AND company_id=:company AND active=1 LIMIT 1'.($lock?' FOR UPDATE':''));$q->execute(['id'=>$id,'company'=>$companyId]);$row=$q->fetch();if(!$row||!in_array($row['location_usage'],$usages,true))throw new InvalidArgumentException('Select an active location with the required Inventory location type.');return$row;}
    private function workCenter(int $id,int $companyId):?array{$q=$this->pdo->prepare('SELECT * FROM manufacturing_work_centers WHERE id=:id AND company_id=:company LIMIT 1');$q->execute(['id'=>$id,'company'=>$companyId]);$row=$q->fetch();return$row?:null;}
    private function bomForCompany(int $id,int $companyId):?array{$q=$this->pdo->prepare('SELECT * FROM manufacturing_boms WHERE id=:id AND company_id=:company LIMIT 1');$q->execute(['id'=>$id,'company'=>$companyId]);$row=$q->fetch();return$row?:null;}
    private function sameUomCategory(int $uomId,int $productUomId,int $companyId,string $message):void{$q=$this->pdo->prepare('SELECT a.category_id=b.category_id FROM units_of_measure a JOIN uom_categories ac ON ac.id=a.category_id JOIN units_of_measure b ON b.id=:product_uom JOIN uom_categories bc ON bc.id=b.category_id WHERE a.id=:uom AND a.active=1 AND b.active=1 AND ac.active=1 AND bc.active=1 AND (a.company_id IS NULL OR a.company_id=:a_company) AND (b.company_id IS NULL OR b.company_id=:b_company) AND (ac.company_id IS NULL OR ac.company_id=:ac_company) AND (bc.company_id IS NULL OR bc.company_id=:bc_company)');$q->execute(['uom'=>$uomId,'product_uom'=>$productUomId,'a_company'=>$companyId,'b_company'=>$companyId,'ac_company'=>$companyId,'bc_company'=>$companyId]);if(!(bool)$q->fetchColumn())throw new InvalidArgumentException($message);}
    private function quantityInProductUom(string $quantity,int $moveUomId,int $productUomId,int $companyId):string{$query=$this->pdo->prepare('SELECT CAST((CAST(:quantity AS DECIMAL(20,6))*CAST(move_uom.factor_to_reference AS DECIMAL(20,10))/CAST(product_uom.factor_to_reference AS DECIMAL(20,10))) AS DECIMAL(20,6)) FROM units_of_measure move_uom JOIN units_of_measure product_uom ON product_uom.id=:product_uom WHERE move_uom.id=:move_uom AND move_uom.active=1 AND product_uom.active=1 AND move_uom.category_id=product_uom.category_id AND (move_uom.company_id IS NULL OR move_uom.company_id=:move_company) AND (product_uom.company_id IS NULL OR product_uom.company_id=:product_company)');$query->execute(['quantity'=>$quantity,'product_uom'=>$productUomId,'move_uom'=>$moveUomId,'move_company'=>$companyId,'product_company'=>$companyId]);$converted=$query->fetchColumn();if($converted===false)throw new InvalidArgumentException('The Manufacturing Order unit cannot be converted into the finished product unit.');$this->assertSql('CAST(:converted AS DECIMAL(20,6))>0',['converted'=>$converted],'The converted finished quantity is below the product unit precision.');return(string)$converted;}
    private function costingMethod(int $productId,int $companyId):string{$q=$this->pdo->prepare('SELECT COALESCE(o.costing_method,s.costing_method,c.costing_method) FROM products p JOIN product_categories c ON c.id=p.category_id LEFT JOIN inventory_accounting_settings s ON s.company_id=p.company_id LEFT JOIN product_category_accounting_overrides o ON o.company_id=p.company_id AND o.category_id=p.category_id WHERE p.id=:product AND p.company_id=:company');$q->execute(['product'=>$productId,'company'=>$companyId]);return(string)$q->fetchColumn();}
    private function lockedOrder(int $id,Authorization $authorization):array{$q=$this->pdo->prepare('SELECT * FROM manufacturing_orders WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$order=$q->fetch();if(!$order||!$authorization->canAccessCompany((int)$order['company_id']))throw new InvalidArgumentException('Manufacturing Order was not found in an allowed company.');return$order;}
    private function lockedWorkOrder(int $id,Authorization $authorization):array{$q=$this->pdo->prepare('SELECT w.* FROM manufacturing_work_orders w JOIN manufacturing_orders o ON o.id=w.order_id WHERE w.id=:id FOR UPDATE');$q->execute(['id'=>$id]);$work=$q->fetch();if(!$work||!$authorization->canAccessCompany((int)$work['company_id']))throw new InvalidArgumentException('Work Order was not found in an allowed company.');return$work;}
    private function workOrder(int $id):?array{$q=$this->pdo->prepare('SELECT w.* FROM manufacturing_work_orders w WHERE w.id=:id');$q->execute(['id'=>$id]);$row=$q->fetch();return$row?:null;}
    private function dateTime(mixed $value,string $timezone):?string{if($value===null||$value==='')return null;$date=str_replace('T',' ',(string)$value);if(preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/',$date))$date.=':00';$zone=$this->timezone($timezone);$parsed=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$date,$zone);$errors=DateTimeImmutable::getLastErrors();if(!$parsed||($errors&&($errors['warning_count']||$errors['error_count']))||$parsed->format('Y-m-d H:i:s')!==$date)throw new InvalidArgumentException('Scheduled date must be a valid local date and time.');return$parsed->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}
    private function displayDateTime(?string $value,string $timezone):?string{if($value===null)return null;return(new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone($this->timezone($timezone))->format('Y-m-d H:i:s');}
    private function timezone(string $value):DateTimeZone{try{return new DateTimeZone($value);}catch(\Throwable){throw new InvalidArgumentException('The company timezone is invalid.');}}
    private function companyTimezone(int $companyId):string{$query=$this->pdo->prepare('SELECT timezone FROM companies WHERE id=:company AND active=1 LIMIT 1');$query->execute(['company'=>$companyId]);$timezone=$query->fetchColumn();if($timezone===false)throw new InvalidArgumentException('The selected company is not active.');return(string)($timezone?:'UTC');}
    private function companyCurrency(int $companyId):string{$query=$this->pdo->prepare('SELECT currency_code FROM companies WHERE id=:company AND active=1 LIMIT 1');$query->execute(['company'=>$companyId]);$currency=$query->fetchColumn();if($currency===false)throw new InvalidArgumentException('The selected company is not active.');return(string)($currency?:'BDT');}
    private function date(mixed $value):?string{if($value===null||$value==='')return null;$date=(string)$value;$parsed=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$parsed||$parsed->format('Y-m-d')!==$date)throw new InvalidArgumentException('Expiration date must be a valid YYYY-MM-DD date.');return$date;}
    private function text(mixed $value,string $label,int $max,bool $required):string{$text=trim((string)$value);if($required&&$text==='')throw new InvalidArgumentException($label.' is required.');if(mb_strlen($text)>$max)throw new InvalidArgumentException($label.' must be '.$max.' characters or fewer.');return$text;}
    private function decimal(mixed $value,string $label,bool $positive):string{$text=trim((string)$value);if(!preg_match('/^\d{1,14}(?:\.\d{1,6})?$/',$text))throw new InvalidArgumentException($label.' must be a non-negative number with at most 6 decimal places.');$q=$this->pdo->prepare('SELECT CAST(:value AS DECIMAL(20,6)) '.($positive?'>':'>=').' 0'.($positive?' AND CAST(:value2 AS DECIMAL(20,6))>0':''));$params=['value'=>$text];if($positive)$params['value2']=$text;$q->execute($params);if(!(bool)$q->fetchColumn())throw new InvalidArgumentException($label.' must be greater than zero.');[$whole,$fraction]=array_pad(explode('.',$text,2),2,'');$whole=ltrim($whole,'0')?:'0';return$whole.'.'.str_pad($fraction,6,'0');}
    private function assertScale(mixed $value,int $scale,string $label):void{$text=trim((string)$value);if(!preg_match('/^\d{1,14}(?:\.\d+)?$/',$text))throw new InvalidArgumentException($label.' must be a non-negative decimal number.');$fraction=explode('.',$text,2)[1]??'';if(strlen($fraction)>$scale)throw new InvalidArgumentException($label.' supports at most '.$scale.' decimal places.');}
    private function positiveId(mixed $value,string $label):int{$id=filter_var($value,FILTER_VALIDATE_INT);if($id===false||$id<1)throw new InvalidArgumentException($label.' must be a positive integer.');return(int)$id;}
    private function boolean(mixed $value,string $label):int{if(is_bool($value))return$value?1:0;if($value===0||$value===1||$value==='0'||$value==='1')return(int)$value;throw new InvalidArgumentException($label.' must be true or false.');}
    private function rejectUnknown(array $input,array $allowed):void{$unknown=array_diff(array_keys($input),$allowed);if($unknown)throw new InvalidArgumentException('Unsupported fields: '.implode(', ',$unknown));}
    private function assertSql(string $expression,array $parameters,string $message):void{$query=$this->pdo->prepare('SELECT CASE WHEN '.$expression.' THEN 1 ELSE 0 END');$query->execute($parameters);if(!(bool)$query->fetchColumn())throw new InvalidArgumentException($message);}
    private function add(string $a,string $b):string{$q=$this->pdo->prepare('SELECT CAST(CAST(:a AS DECIMAL(20,6))+CAST(:b AS DECIMAL(20,6)) AS DECIMAL(20,6))');$q->execute(['a'=>$a,'b'=>$b]);return(string)$q->fetchColumn();}
    private function subtract(string $a,string $b):string{$q=$this->pdo->prepare('SELECT CAST(CAST(:a AS DECIMAL(20,6))-CAST(:b AS DECIMAL(20,6)) AS DECIMAL(20,6))');$q->execute(['a'=>$a,'b'=>$b]);return(string)$q->fetchColumn();}
    private function multiply(string $a,string $b):string{$q=$this->pdo->prepare('SELECT CAST(ROUND(CAST(:a AS DECIMAL(20,6))*CAST(:b AS DECIMAL(20,6)),6) AS DECIMAL(20,6))');$q->execute(['a'=>$a,'b'=>$b]);return(string)$q->fetchColumn();}
    private function divide(string $a,string $b):string{$q=$this->pdo->prepare('SELECT CASE WHEN CAST(:zero AS DECIMAL(20,6))=0 THEN 0 ELSE CAST(ROUND(CAST(:a AS DECIMAL(20,6))/CAST(:b AS DECIMAL(20,6)),6) AS DECIMAL(20,6)) END');$q->execute(['zero'=>$b,'a'=>$a,'b'=>$b]);return(string)$q->fetchColumn();}
    private function absolute(string $a):string{$q=$this->pdo->prepare('SELECT CAST(ABS(CAST(:a AS DECIMAL(20,6))) AS DECIMAL(20,6))');$q->execute(['a'=>$a]);return(string)$q->fetchColumn();}
    private function atomic(callable $callback):mixed{$owns=!$this->pdo->inTransaction();if($owns)$this->pdo->beginTransaction();try{$result=$callback();if($owns)$this->pdo->commit();return$result;}catch(Throwable$error){if($owns&&$this->pdo->inTransaction())$this->pdo->rollBack();throw$error;}}
    private function audit(int $company,int $actor,string $event,string $model,int $record,?array $before,?array $after,string $remote):void{$ip=filter_var($remote,FILTER_VALIDATE_IP)?inet_pton($remote):null;$q=$this->pdo->prepare('INSERT INTO audit_events (company_id,user_id,event_key,model_key,record_id,old_values,new_values,ip_address) VALUES (:company,:user,:event,:model,:record,:old,:new,:ip)');$q->bindValue(':company',$company,PDO::PARAM_INT);$q->bindValue(':user',$actor,PDO::PARAM_INT);$q->bindValue(':event',$event);$q->bindValue(':model',$model);$q->bindValue(':record',$record,PDO::PARAM_INT);$q->bindValue(':old',$before===null?null:json_encode($before,JSON_THROW_ON_ERROR),$before===null?PDO::PARAM_NULL:PDO::PARAM_STR);$q->bindValue(':new',$after===null?null:json_encode($after,JSON_THROW_ON_ERROR),$after===null?PDO::PARAM_NULL:PDO::PARAM_STR);$q->bindValue(':ip',$ip,$ip===null?PDO::PARAM_NULL:PDO::PARAM_LOB);$q->execute();}
}
